#showcase { min-height: 100vh; color: #2a2233; background: #f5f2f8; font: 14px/1.5 system-ui, sans-serif; }
#showcase, #showcase * { box-sizing: border-box; }
#showcase { display: grid; grid-template-rows: auto 1fr; }
#showcase .toolbar { display: flex; align-items: center; gap: 16px; padding: 12px 20px; background: #fff; border-bottom: 1px solid #e4ddf0; }
#showcase h1 { margin: 0 auto 0 0; font-size: 16px; font-weight: 700; }
#showcase label { font-weight: 600; }
#showcase select { width: min(52vw, 520px); min-height: 38px; padding: 8px 12px; border: 1px solid #d6cce6; border-radius: 8px; color: inherit; background: #fff; font: inherit; }
#showcase main { min-height: 0; padding: 12px; }
#showcase iframe { display: block; width: 100%; height: calc(100vh - 78px); border: 1px solid #e4ddf0; border-radius: 8px; background: #fff; }
@media (max-width: 640px) {
  #showcase .toolbar { flex-wrap: wrap; gap: 8px; padding: 10px 12px; }
  #showcase h1 { width: 100%; }
  #showcase select { flex: 1; width: auto; }
  #showcase main { padding: 8px; }
  #showcase iframe { height: calc(100vh - 122px); }
}

